92	            String corrects, String ref, String tags) {
93	        Person person = person(sheetId, personId);
94	        LocalDate dated = date != null ? date : entryDateOr(sheetId);
95	        // The terms are fixed now, those in force on the claim's date; the due-by counts them in business days.
96	        int terms = termsOf(sheetId, person, dated);
97	        LocalDate dueBy = holidays.dueBy(sheetId, dated, terms);
98	        refuseIfClosed(sheetId, dueBy);
99	        refuseIfRetired(person, dated);
100	        refuseIfNotCorrecting(sheetId, personId, amount, corrects);
101	        String reference = refOf(ref);
102	        refuseIfRefUsed(sheetId, reference, null);
103	        Rollup.Snapshot before = rollup.snapshot(sheetId);
104	        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note), corrects, terms, dueBy);
105	        claim.setRef(reference);
106	        List<String> tagged = tagsOf(tags);
107	        claim.setTags(tagged);
108	        // The sheet is locked (refuseIfClosed), so no other claim takes the same place.
109	        claim.setListed(claims.lastListed(sheetId) + 1);
110	        boolean late = periods.isSoftClosedOn(sheetId, dueBy);
111	        if (late) claim.markLateEntry();
112	        claim = claims.saveAndFlush(claim);
113	        useTags(sheetId, tagged);
114	        logStatus(sheetId, user, person, claim);
115	        recordChange("CLAIM_ADDED", user, person, claim, claim.getNumber(),
116	                (reference == null ? "" : " ref=" + reference)
117	                        + (tagged.isEmpty() ? "" : " tags=" + String.join(",", tagged)));
118	        if (late) recordChange("LATE_ENTRY", user, person, claim);
