268	    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus next, String reason) {
269	        Claim claim = claims.findForUpdate(id, sheetId)
270	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
271	        refuseIfClosed(sheetId, claim.getDueBy());
272	        boolean voidingSettled = next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
273	        if (voidingSettled) {
274	            refuseUnlessSettledVoidable(sheetId, user, claim);
275	        } else if (!claim.getStatus().canBecome(next)) {
276	            throw new ResponseStatusException(HttpStatus.CONFLICT,
277	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
278	        } else {
279	            settings.refuseUnlessPermitted(sheetId, user, ACTIONS.get(next),
280	                    "Your role may not " + ACTIONS.get(next) + " a claim on this sheet.");
281	        }
282	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
283	            throw new ResponseStatusException(HttpStatus.CONFLICT,
284	                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be settled before then.");
285	        }
286	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
287	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
288	                    "The user who opened a claim cannot settle it.");
289	        }
290	        if (next == ClaimStatus.SETTLED && user.equals(claim.getEditedBy())) {
291	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
292	                    "The user who last edited a claim cannot settle it.");
293	        }
294	        String voidReason = next == ClaimStatus.VOID ? voidReasons.reasonToVoid(sheetId, reason) : null;
295	        Person person = person(sheetId, claim.getPersonId());
296	        // Worked out while the claim is still open: settling freezes the due, its late charge included.
297	        BigDecimal dueNow = next == ClaimStatus.SETTLED ? due(sheetId, person, claim) : null;
298	        if (next == ClaimStatus.SETTLED) refuseIfUnproven(sheetId, person, claim, dueNow);
299	        if (next == ClaimStatus.OPEN) refuseIfUnnoted(sheetId, claim, due(sheetId, person, claim));
300	        if (next == ClaimStatus.OPEN) refuseIfCapped(sheetId, claim);
301	        // Settled one at a time until a bulk settle marks it with its batch.
302	        if (next == ClaimStatus.SETTLED) claim.setSettleBatch(null);
303	        if (next == ClaimStatus.SETTLED && isAboveClerkLimit(sheetId, user, dueNow)) next = ClaimStatus.PENDING;
304	        Rollup.Snapshot before = rollup.snapshot(sheetId);
305	        String number = next == ClaimStatus.OPEN ? nextNumber(sheetId, claim) : claim.getNumber();
306	        claim.setStatus(next);
307	        if (next == ClaimStatus.OPEN) claim.setOpenedBy(user);
308	        // A voided claim keeps its number, which is never given to another claim.
309	        claim.setNumber(number);
310	        if (next == ClaimStatus.SETTLED) claim.setSettledDue(dueNow);
311	        if (next == ClaimStatus.VOID) claim.setVoidReason(voidReason);
312	        logStatus(sheetId, user, person, claim);
313	        Claim saved = claims.saveAndFlush(claim);
314	        String event = EVENTS.get(next);
315	        if (next == ClaimStatus.SETTLED) {
316	            recordChange(event, user, person, saved, number, " due=" + text(saved.getSettledDue()));
317	            notifyWatchers(user, person, saved);
318	        } else if (voidingSettled) {
319	            recordChange(event, user, person, saved, number, " reversed=" + text(saved.getSettledDue())
320	                    + reasonField(voidReason));
321	        } else {
322	            recordChange(event, user, person, saved, number, reasonField(voidReason));
323	        }
324	        rollup.recordChanges(user, before);
325	        return saved;
326	    }
