410	        refuseIfClosed(sheetId, claim.getDueBy());
411	        if (claim.getStatus() != ClaimStatus.OPEN) {
412	            throw new ResponseStatusException(HttpStatus.CONFLICT,
413	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one can.");
414	        }
415	        if (claim.isDeferredOn(sheets.today(sheetId))) {
416	            throw new ResponseStatusException(HttpStatus.CONFLICT,
