421	                    "The amount split off must be more than 0.00 and less than the claim's amount.");
422	        }
423	        Person person = person(sheetId, claim.getPersonId());
424	        // The terms are fixed now, those in force on the claim's date; the due-by counts them in business days.
425	        int terms = termsOf(sheetId, person, claim.getDate());
426	        LocalDate dueBy = holidays.dueBy(sheetId, claim.getDate(), terms);
427	        refuseIfClosed(sheetId, dueBy);
428	        Rollup.Snapshot before = rollup.snapshot(sheetId);
429	        Claim split = claim.splitOff(part, null, user, terms, dueBy, sheets.today(sheetId));
430	        String number = nextNumber(sheetId, split);
431	        split.setNumber(number);
432	        // Split off into a soft-closed period, the new claim is a late entry of it.
433	        if (periods.isSoftClosedOn(sheetId, dueBy)) split.markLateEntry();
434	        split.setListed(claims.lastListed(sheetId) + 1);
435	        Claim saved = claims.saveAndFlush(claim);
436	        split = claims.saveAndFlush(split);
437	        logStatus(sheetId, user, person, split);
438	        recordChange("CLAIM_SPLIT", user, person, saved, saved.getNumber(), " into=" + number);
439	        recordChange("CLAIM_OPENED", user, person, split);
440	        rollup.recordChanges(user, before);
441	        return new Split(saved, split);
442	    }
