572	    /** Move a claim as {@link #reassign(String, String, long, long)} does; a claim moved with others to
573	     *  its own person is not refused but re-listed as that person's newest claim, a numbered one taking the next number. */
574	    @Transactional
575	    public Claim reassign(String sheetId, String user, long id, long toPersonId, boolean withOthers) {
576	        Claim claim = claims.findForUpdate(id, sheetId)
577	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
578	        refuseIfClosed(sheetId, claim.getDueBy());
579	        settings.refuseUnlessPermitted(sheetId, user, "reassign",
580	                "Your role may not move a claim to another person on this sheet.");
581	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
582	            throw new ResponseStatusException(HttpStatus.CONFLICT,
583	                    "A " + claim.getStatus() + " claim cannot be moved to another person.");
584	        }
585	        Person from = person(sheetId, claim.getPersonId());
586	        Person to = person(sheetId, toPersonId);
587	        if (!withOthers && from.getId().equals(to.getId())) {
588	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s.");
589	        }
590	        refuseIfRetired(to, claim.getDate());
591	        if (!from.getId().equals(to.getId())) {
592	            refuseIfClosed(sheetId, holidays.dueBy(sheetId, claim.getDate(), termsOf(sheetId, to, claim.getDate())));
593	        }
594	        Rollup.Snapshot before = rollup.snapshot(sheetId);
595	        claim.moveTo(to.getId(), claims.lastListed(sheetId) + 1, sheets.today(sheetId));
596	        // Moved (to another person, or with others to its own), a numbered claim takes the next number;
597	        // its old one is not reused.
598	        if (claim.getNumber() != null && (withOthers || !from.getId().equals(to.getId()))) {
599	            claim.setNumber(nextNumber(sheetId, claim));
600	        }
601	        Claim saved = claims.saveAndFlush(claim);
602	        recordChange("CLAIM_REASSIGNED", user, to, saved, saved.getNumber(),
603	                " from=" + from.getName() + " to=" + to.getName());
604	        rollup.recordChanges(user, before);
605	        return saved;
606	    }
