608	    /** Approve a PENDING claim: it is SETTLED, its due (its live figure and any late charge) frozen
609	     *  now. Refused unless the user is a steward of the sheet other than the one who opened or last
610	     *  edited it. */
611	    @Transactional
612	    public Claim approve(String sheetId, String user, long id) {
613	        Claim claim = pending(sheetId, user, id);
614	        if (user.equals(claim.getOpenedBy())) {
615	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
616	                    "The user who opened a claim cannot approve it.");
617	        }
618	        if (user.equals(claim.getEditedBy())) {
619	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
620	                    "The user who last edited a claim cannot approve it.");
621	        }
622	        Person person = person(sheetId, claim.getPersonId());
623	        BigDecimal dueNow = due(sheetId, person, claim);
624	        refuseIfUnproven(sheetId, person, claim, dueNow);
625	        Rollup.Snapshot before = rollup.snapshot(sheetId);
626	        claim.setStatus(ClaimStatus.SETTLED);
627	        claim.setSettledDue(dueNow);
628	        logStatus(sheetId, user, person, claim);
629	        Claim saved = claims.saveAndFlush(claim);
630	        recordChange("CLAIM_APPROVED", user, person, saved, saved.getNumber(), " due=" + text(saved.getSettledDue()));
631	        notifyWatchers(user, person, saved);
632	        rollup.recordChanges(user, before);
633	        return saved;
634	    }
