636	    /** Re-settle a SETTLED claim: its due is frozen again at what it would be today as an open claim
637	     *  bound by no statement (today's rates, grades, floor and late charge). Refused unless the user is
638	     *  a steward of the sheet, and for a claim that is not SETTLED or is dated inside a closed period. */
639	    @Transactional
640	    public Claim resettle(String sheetId, String user, long id) {
641	        Claim claim = claims.findForUpdate(id, sheetId)
642	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
643	        refuseIfClosed(sheetId, claim.getDueBy());
644	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
645	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim.");
646	        }
647	        if (claim.getStatus() != ClaimStatus.SETTLED) {
648	            throw new ResponseStatusException(HttpStatus.CONFLICT,
649	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can.");
650	        }
651	        Person person = person(sheetId, claim.getPersonId());
652	        BigDecimal old = claim.getSettledDue();
653	        BigDecimal dueNow = LateCharge.dueAsOpen(claim, dueNow(sheetId, person, claim),
654	                settings.floor(sheetId, claim.getDate()), sheets.today(sheetId), grace(sheetId, person, claim),
655	                settings.dated(sheetId)::latePctOn, rounding(sheetId, claim));
656	        Rollup.Snapshot before = rollup.snapshot(sheetId);
657	        claim.setSettledDue(dueNow);
658	        logStatus(sheetId, user, person, claim);
659	        Claim saved = claims.saveAndFlush(claim);
660	        recordChange("CLAIM_RESETTLED", user, person, saved, saved.getNumber(),
661	                " old=" + text(old) + " new=" + text(saved.getSettledDue()));
662	        notifyWatchers(user, person, saved);
663	        rollup.recordChanges(user, before);
664	        return saved;
665	    }
