701	    /** Refuse voiding a SETTLED claim unless the user is a steward of the sheet and the sheet's today is
702	     *  within {@value #VOID_SETTLED_DAYS} days of the claim's settlement, as its status log records it. */
703	    private void refuseUnlessSettledVoidable(String sheetId, String user, Claim claim) {
704	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
