728	    /** The number a claim takes as it is opened: while the sheet's period numbering is in force (its
729	     *  today on or after the setting's date), the next of the claim's period (the one its due-by falls in), <period name>-<n>, or of
730	     *  claims in no period, X-<n> (each per sheet); otherwise FY<year>-<n>, the next number within the
731	     *  fiscal year its due-by falls in (named by the calendar year it starts in), of the sequence of that
732	     *  year the sheets of its tree share. */
733	    public String nextNumber(String sheetId, Claim claim) {
734	        if (!isPeriodNumbering(sheetId)) {
735	            int year = fiscalYearOf(sheetId, claim.getDueBy() != null ? claim.getDueBy() : claim.getDate());
736	            return "FY" + year + "-" + sheets.nextFiscalYearNumber(sheetId, year);
737	        }
738	        Period period = periodOf(sheetId, claim.getDueBy());
739	        if (period == null) return "X-" + sheets.nextSequenceNumber(sheetId, "none");
740	        return period.getName() + "-" + sheets.nextSequenceNumber(sheetId, "period:" + period.getId());
741	    }
