743	    /** The fiscal year of the sheet the date falls in: the calendar year it starts in. */
744	    private int fiscalYearOf(String sheetId, LocalDate date) {
745	        int startMonth = settings.fiscalStartMonth(sheetId);
746	        return date.getMonthValue() >= startMonth ? date.getYear() : date.getYear() - 1;
747	    }
