755	    /** The sheet's period whose dates contain the date; null when none does. */
756	    private Period periodOf(String sheetId, LocalDate date) {
757	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
758	                .filter((p) -> p.contains(date)).findFirst().orElse(null);
759	    }
