761	    /** Refuse settling or approving a claim with no proofs whose due is above the proof threshold in force
762	     *  on the claim's date: its person's grade's then when one is set, else the sheet's (a due of n/a, or
763	     *  no threshold, needs none). */
764	    private void refuseIfUnproven(String sheetId, Person person, Claim claim, BigDecimal due) {
765	        if (due == null || claim.getProofs() > 0) return;
766	        BigDecimal threshold = settings.proofThreshold(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
767	        if (threshold != null && due.compareTo(threshold) > 0) {
768	            throw new ResponseStatusException(HttpStatus.CONFLICT,
769	                    "The claim's due is above the proof threshold of " + threshold.toPlainString()
770	                            + "; add a proof before it is settled.");
771	        }
772	    }
