774	    /** Refuse opening a claim with an empty note whose due is above the sheet's note threshold in force
775	     *  on the claim's date (a due of n/a, or no threshold, needs none). */
776	    private void refuseIfUnnoted(String sheetId, Claim claim, BigDecimal due) {
777	        if (due == null || (claim.getNote() != null && !claim.getNote().isBlank())) return;
778	        BigDecimal threshold = settings.noteThreshold(sheetId, claim.getDate());
779	        if (threshold != null && due.compareTo(threshold) > 0) {
780	            throw new ResponseStatusException(HttpStatus.CONFLICT,
781	                    "The claim's due is above the note threshold of " + threshold.toPlainString()
782	                            + "; add a note before it is opened.");
783	        }
784	    }
