786	    /** Refuse opening a claim whose period (the one its due-by falls in) caps its person's claims, when
787	     *  the person already has that many OPEN or PENDING claims in it. The sheet is locked, so two opens
788	     *  cannot both pass the cap. */
789	    private void refuseIfCapped(String sheetId, Claim claim) {
790	        if (claim.getDueBy() == null) return;
791	        Period period = periodOf(sheetId, claim.getDueBy());
792	        if (period == null || period.getCap() == null) return;
793	        long held = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
794	                .filter((c) -> !c.getId().equals(claim.getId()) && c.getPersonId().equals(claim.getPersonId())
795	                        && c.getStatus().isOpen() && c.getDueBy() != null && period.contains(c.getDueBy()))
796	                .count();
797	        if (held >= period.getCap()) {
798	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person already has " + period.getCap()
799	                    + " open claims in period " + period.getName() + ".");
800	        }
801	    }
