856	        return LateCharge.dueOf(claim, figure(sheetId, person, claim), settings.floor(sheetId, claim.getDate()),
857	                sheets.today(sheetId), grace(sheetId, person, claim),
858	                settings.dated(sheetId)::latePctOn, rounding(sheetId, claim));
859	    }
860	
861	    /** The grace days of the person's grade in force on the claim's date, in force on that date; 0 when none. */
862	    private int grace(String sheetId, Person person, Claim claim) {
863	        return settings.dated(sheetId).graceOn(person.gradeOn(claim.getDate()), claim.getDate());
864	    }
865	
866	    /** The figure under the claim's due, before any late charge and floor: the due fixed when it was settled, else the figure
867	     *  its person's last statement bound it to (unless it is PENDING, which no statement binds), else its live due;
868	     *  null when that is n/a. */
869	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
870	        if (claim.getSettledDue() != null) return claim.getSettledDue();
871	        if (claim.isBound()) return claim.getStatedDue();
872	        return dueNow(sheetId, person, claim);
873	    }
874	
875	    /** The claim's rate figure now: at the rate in force on the claim's date of its person's grade in
876	     *  force on that date, rounded as the claim's {@link Rounding} decides, before any late charge and
877	     *  floor; null when no rate of the grade applies by then. */
878	    private BigDecimal dueNow(String sheetId, Person person, Claim claim) {
879	        Rate rate = rates.inForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
880	        if (rate == null) return null;
881	        return claim.getAmount().multiply(rate.getPct()).divide(BigDecimal.valueOf(100), 2,
882	                rounding(sheetId, claim));
883	    }
884	
885	    /** How many claims a candidate rate would change and by how much in all. */
886	    public record RatePreview(int count, BigDecimal diff) {
887	    }
888	
889	    /** What a candidate percent for a grade, applied on every date, would do to the OPEN and PENDING claims of
890	     *  people on that grade on the claim's date: how many would show a different due, and the sum of new due
891	     *  less current due (an n/a due counting as 0.00). A claim bound by a statement does not change; nothing is saved. */
892	    @Transactional(readOnly = true)
893	    public RatePreview previewRate(String sheetId, Grade grade, BigDecimal pct) {
894	        Map<Long, Person> byId = new HashMap<>();
895	        for (Person p : people.findInListOrder(sheetId)) byId.put(p.getId(), p);
896	        int count = 0;
897	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
898	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
899	            if (!claim.getStatus().isOpen() || claim.isBound() || claim.getSettledDue() != null) continue;
900	            Person person = byId.get(claim.getPersonId());
901	            if (person == null || person.gradeOn(claim.getDate()) != grade) continue;
902	            RoundingMode rounding = rounding(sheetId, claim);
903	            BigDecimal figure = claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding);
904	            BigDecimal next = LateCharge.dueOf(claim, figure, settings.floor(sheetId, claim.getDate()),
905	                    sheets.today(sheetId), grace(sheetId, person, claim), settings.dated(sheetId)::latePctOn, rounding);
906	            BigDecimal current = due(sheetId, person, claim);
907	            if (current != null && current.compareTo(next) == 0) continue;
908	            count++;
909	            diff = diff.add(next.subtract(current == null ? BigDecimal.ZERO : current));
910	        }
911	        return new RatePreview(count, diff.setScale(2));
912	    }
913	
914	    /** How the claim's live figures round under the sheet's policy date: by the date of the claim a
915	     *  correction corrects, else by its own. */
916	    private RoundingMode rounding(String sheetId, Claim claim) {
917	        return rounding(sheetId, claim, sheets.today(sheetId));
918	    }
919	
920	    /** How the claim's figures round under the sheet's policy date with the date given standing in for
921	     *  the sheet's today. */
922	    public RoundingMode rounding(String sheetId, Claim claim, LocalDate today) {
923	        Claim corrected = claim.isCorrection() && claim.getCorrects() != null
924	                ? claims.findBySheetIdAndPersonIdAndNumber(sheetId, claim.getPersonId(), claim.getCorrects()).orElse(null)
925	                : null;
926	        return Rounding.of(Rounding.dateOf(claim, corrected),
927	                Rounding.policyDate(settings.policyDate(sheetId), today));
928	    }
929	
930	    /** The audit field of the reason a claim was voided with; blank when there is none. */
931	    private static String reasonField(String voidReason) {
932	        return voidReason == null ? "" : " reason=" + voidReason;
933	    }
934	
935	    /** Log the status the claim has just taken, with its due as worked out now. */
936	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
937	        claim.logStatus(user, sheets.today(sheetId), due(sheetId, person, claim));
938	    }
939	
940	    private void recordChange(String event, String user, Person person, Claim claim) {
941	        recordChange(event, user, person, claim, claim.getNumber(), "");
942	    }
943	
944	    /** The claim's audit line; a claim with a number carries it, then any extra fields. */
945	    private void recordChange(String event, String user, Person person, Claim claim, String number, String extra) {
946	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
947	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
948	                + (number == null ? "" : " number=" + number) + extra);
949	    }
950	
951	    /** Tell each user watching the person, in the order they started watching, that the claim was settled. */
952	    private void notifyWatchers(String user, Person person, Claim claim) {
953	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
954	            audit.recordOnCommit("NOTIFY sheet=" + claim.getSheetId() + " by=" + user + " user=" + watch.getUserName()
955	                    + " person=" + person.getName() + " number=" + claim.getNumber());
956	        }
957	    }
958	
959	    private LocalDate dateOr(String sheetId, LocalDate date) {
960	        return date != null ? date : sheets.today(sheetId);
961	    }
962	
963	    /** The date a new claim given none takes: the sheet's entry date while it is set, else its today. */
964	    private LocalDate entryDateOr(String sheetId) {
965	        LocalDate entry = settings.entryDate(sheetId);
966	        return entry != null ? entry : sheets.today(sheetId);
967	    }
968	
969	    /** Every tag ever used on the sheet, by name. */
970	    @Transactional(readOnly = true)
971	    public List<String> tags(String sheetId) {
972	        return sheetTags.findBySheetIdOrderByNameAsc(sheetId).stream().map(SheetTag::getName).toList();
973	    }
974	
975	    /** Keep the tags as used on the sheet. */
976	    public void useTags(String sheetId, List<String> tagged) {
977	        for (String tag : tagged) {
978	            if (!sheetTags.existsBySheetIdAndName(sheetId, tag)) sheetTags.save(new SheetTag(sheetId, tag));
979	        }
980	    }
981	
982	    /** Tags as typed, comma separated: each trimmed and lower-cased, blanks and repeats dropped, sorted. */
983	    public static List<String> tagsOf(String tags) {
984	        if (tags == null) return List.of();
985	        return Arrays.stream(tags.split(",")).map(t -> t.trim().toLowerCase(Locale.ROOT)).filter(t -> !t.isEmpty())
986	                .distinct().sorted().toList();
987	    }
988	
989	    /** A reference as given, trimmed; none when blank. */
990	    public static String refOf(String ref) {
991	        return ref == null || ref.isBlank() ? null : ref.trim();
992	    }
993	
994	    private static String noteOf(String note) {
995	        return note == null ? "" : note.trim();
996	    }
997	}
