  to: string | null;
}

/** Whether a date (yyyy-mm-dd) falls within one of the holds. */
export function heldOn(holds: readonly HoldView[], date: string): boolean {
  return holds.some((h) => (h.from === null || h.from <= date) && (h.to === null || date <= h.to));
}

