import { DatedValue, valueOn } from './dated';

/** The floor of a sheet that has not set one, in cents. */
export const DEFAULT_FLOOR_CENTS = 100;

// The loaded sheet's floor, the least a claim's live due can be, shared by the screens that show due.
// It is dated: a claim's floor is the one in force on the claim's date.
@Injectable({ providedIn: 'root' })
export class SheetFloor {
  /** The floor's values from their from-dates, in date order. */
  readonly history = signal<readonly DatedValue[]>([]);

  /** The floor in force on the date, in cents; the starting floor before every from-date. */
  centsOn(date: string | undefined): number {
    const value = valueOn(this.history(), date);
    return value === null ? DEFAULT_FLOOR_CENTS : Math.round(Number(value) * 100);
  }
}
import { Injectable, computed, inject, signal } from '@angular/core';
import { Session } from '../../core/session';
import { DatedValue, valueOn } from './dated';

// The loaded sheet's cap, the most a person's due-total can be, shared by the screens that show due.
// It is dated: the cap is the one in force on the sheet's today.
@Injectable({ providedIn: 'root' })
export class SheetCap {
  private readonly session = inject(Session);

  /** The cap's values from their from-dates, in date order. */
  readonly history = signal<readonly DatedValue[]>([]);

  /** The cap in force on the sheet's today in cents, or null when there is no cap. */
  readonly cents = computed(() => {
    const value = valueOn(this.history(), this.session.sheet()?.today);
    return value === null ? null : Math.round(Number(value) * 100);
  });
}
import { Injectable, signal } from '@angular/core';
import { Grade } from '../people/people-api';
import { DatedValue, valueOn } from './dated';

// The loaded sheet's grace days by grade, shared by the screens that show overdue claims and due. They are
// dated: a claim takes the grace of its person's grade in force on its date, in force on that date; it is
// overdue only once its due-by plus them is before the sheet's today, and its late charge counts from then.
@Injectable({ providedIn: 'root' })
export class SheetGrace {
  /** Each grade's grace days from their from-dates, in date order. */
  readonly history = signal<Partial<Record<Grade, readonly DatedValue[]>>>({});

  /** The grace days of the grade in force on the date; none (0) when it has none then, or there is no grade. */
  daysOn(grade: Grade | null, date: string): number {
    if (grade === null) return 0;
    const value = valueOn(this.history()[grade] ?? [], date);
    return value === null ? 0 : Number(value);
  }
}

